const cfg = $('Config').first().json;
const staticData = $getWorkflowStaticData('global');
staticData.sentNews = staticData.sentNews || {};

const raw = items[0].json;
const list = Array.isArray(raw) ? raw : (Array.isArray(raw.data) ? raw.data : []);
const now = Date.now();
const preMs = (Number(cfg.preNewsMinutes) || 30) * 60 * 1000;
const postMs = (Number(cfg.postNewsMinutes) || 20) * 60 * 1000;
const countries = new Set(['USD', 'EUR']);

const out = [];
for (const ev of list) {
  const impact = String(ev.impact || '').toLowerCase();
  if (impact !== 'high') continue;
  const country = String(ev.country || '').toUpperCase();
  if (!countries.has(country)) continue;

  const ts = Date.parse(ev.date);
  if (!Number.isFinite(ts)) continue;
  const diff = ts - now;
  if (diff > preMs || diff < -postMs) continue;

  const key = `${ev.date}|${country}|${ev.title}`;
  const bucket = diff >= 0 ? 'pre' : 'post';
  const sentKey = `${key}|${bucket}`;
  if (staticData.sentNews[sentKey]) continue;
  staticData.sentNews[sentKey] = now;

  const mins = Math.round(Math.abs(diff) / 60000);
  const when = diff >= 0 ? `in ${mins} min` : `${mins} min ago`;
  const bias = country === 'USD'
    ? 'Watch USD impulse → possible EURUSD reverse/bounce after spike'
    : 'Watch EUR impulse → possible EURUSD reverse/bounce after spike';

  out.push({
    json: {
      type: 'news',
      title: ev.title,
      country,
      impact: ev.impact,
      forecast: ev.forecast || '—',
      previous: ev.previous || '—',
      when,
      bias,
      telegramChatId: cfg.telegramChatId,
      text: [
        `🚨 EURUSD NEWS (${bucket.toUpperCase()})`,
        ``,
        `${country}: ${ev.title}`,
        `When: ${when}`,
        `Forecast: ${ev.forecast || '—'} | Previous: ${ev.previous || '—'}`,
        ``,
        `Idea: wait for sharp move, then look for bounce/correction`,
        `Bias hint: ${bias}`,
        ``,
        `⚠️ Not a blind entry`
      ].join('\n')
    }
  });
}

// cleanup old keys (7 days)
const week = 7 * 24 * 60 * 60 * 1000;
for (const [k, v] of Object.entries(staticData.sentNews)) {
  if (now - v > week) delete staticData.sentNews[k];
}

return out;

const cfg = $('Config').first().json;
const key = String(cfg.twelveDataApiKey || '').trim();
if (!key) {
  return [];
}
return [{
  json: {
    ...cfg,
    twelveDataApiKey: key,
    outputsize: Math.max(3, Number(cfg.spikeMinutes) + 2)
  }
}];

const cfg = $('Config').first().json;
const staticData = $getWorkflowStaticData('global');
const payload = items[0].json;

if (payload.status === 'error' || !payload.values || !payload.values.length) {
  return [];
}

const values = payload.values
  .map(v => ({ t: v.datetime, c: Number(v.close) }))
  .filter(v => Number.isFinite(v.c))
  .reverse(); // oldest -> newest

if (values.length < 2) return [];

const newest = values[values.length - 1];
const mins = Math.max(1, Number(cfg.spikeMinutes) || 5);
const lookbackIdx = Math.max(0, values.length - 1 - mins);
const older = values[lookbackIdx];

const move = newest.c - older.c;
const pips = Math.round(Math.abs(move) * 10000); // EURUSD pip
const threshold = Number(cfg.spikePips) || 35;

if (pips < threshold) {
  return [];
}

const direction = move < 0 ? 'DOWN' : 'UP';
const bounceIdea = move < 0 ? 'Look for LONG bounce / correction up' : 'Look for SHORT pullback / correction down';
const key = `${older.t}->${newest.t}|${direction}|${pips}`;
staticData.sentSpikes = staticData.sentSpikes || {};
if (staticData.sentSpikes[key]) return [];
staticData.sentSpikes[key] = Date.now();

// keep map small
const keys = Object.keys(staticData.sentSpikes);
if (keys.length > 100) {
  for (const k of keys.slice(0, keys.length - 50)) delete staticData.sentSpikes[k];
}

const text = [
  `💥 EURUSD SPIKE`,
  ``,
  `Move: ${direction} ${pips} pips in ~${mins} min`,
  `From: ${older.c.toFixed(5)}`,
  `To:   ${newest.c.toFixed(5)}`,
  ``,
  `Idea: ${bounceIdea}`,
  `Context: current broader pressure has been DOWN on EUR`,
  ``,
  `⚠️ Wait for your entry model. Not FOMO.`
].join('\n');

return [{
  json: {
    type: 'spike',
    pips,
    direction,
    telegramChatId: cfg.telegramChatId,
    text
  }
}];
